package com.distributedexam.dao;
import com.distributedexam.common.ExamEvent; import java.sql.*; import java.util.*;
public class EventDAOImpl implements EventDAO {
 public void create(ExamEvent e)throws Exception{try(Connection c=DBConnection.getConnection();PreparedStatement s=c.prepareStatement("INSERT INTO exam_events(exam_id,room_id,event_type,description,event_timestamp,user_id) VALUES(?,?,?,?,?,?)",Statement.RETURN_GENERATED_KEYS)){n(s,1,e.getExamId());n(s,2,e.getRoomId());s.setString(3,e.getEventType());s.setString(4,e.getDescription());s.setTimestamp(5,e.getEventTimestamp()==null?new Timestamp(System.currentTimeMillis()):e.getEventTimestamp());n(s,6,e.getUserId());s.executeUpdate();try(ResultSet k=s.getGeneratedKeys()){if(k.next())e.setEventId(k.getInt(1));}}}
 public List<ExamEvent> findRecent(int limit)throws Exception{if(limit<1) return List.of();return list("SELECT * FROM exam_events ORDER BY event_timestamp DESC LIMIT ?",limit);} public List<ExamEvent> findByRoom(int roomId)throws Exception{return list("SELECT * FROM exam_events WHERE room_id=? ORDER BY event_timestamp DESC",roomId);}
 private List<ExamEvent> list(String q,int id)throws Exception{List<ExamEvent> out=new ArrayList<>();try(Connection c=DBConnection.getConnection();PreparedStatement s=c.prepareStatement(q)){s.setInt(1,id);try(ResultSet r=s.executeQuery()){while(r.next()){ExamEvent e=new ExamEvent();e.setEventId(r.getInt("event_id"));e.setExamId(v(r,"exam_id"));e.setRoomId(v(r,"room_id"));e.setEventType(r.getString("event_type"));e.setDescription(r.getString("description"));e.setEventTimestamp(r.getTimestamp("event_timestamp"));e.setUserId(v(r,"user_id"));out.add(e);}}}return out;} private static void n(PreparedStatement s,int i,Integer v)throws SQLException{if(v==null)s.setNull(i,Types.INTEGER);else s.setInt(i,v);}private static Integer v(ResultSet r,String c)throws SQLException{int v=r.getInt(c);return r.wasNull()?null:v;}
}
